#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PORT="${1:-8080}"

# Load .env if present
if [[ -f "$ROOT/.env" ]]; then
    # shellcheck disable=SC1091
    source "$ROOT/.env"
fi

# Generate config.js for the preview page
CONFIG="$ROOT/preview/config.js"
cat > "$CONFIG" <<EOF
// Auto-generated by preview.sh — do not edit
window.PGTILER_CONFIG = {
    R2_PUBLIC_URL: '${R2_PUBLIC_URL:-}',
};
EOF

echo "Serving preview at http://localhost:${PORT}"
if [[ -n "${R2_PUBLIC_URL:-}" ]]; then
    echo "R2 layers enabled: ${R2_PUBLIC_URL}"
fi
python3 -m http.server "$PORT" --directory "$ROOT/preview"
